```java
import java.util.ArrayList;
import java.util.Comparator;
import java.util.Scanner;

public class Main {
    static class StringEntry {
        String text;
        int length;

        StringEntry(String text) {
            this.text = text;
            this.length = text.length();
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the number of strings: ");
        int count = Integer.parseInt(scanner.nextLine());

        if (count < 0) {
            System.out.println("The number of strings cannot be negative.");
            return;
        }

        ArrayList<StringEntry> entries = new ArrayList<>();

        for (int i = 0; i < count; i++) {
            System.out.print("Enter string " + (i + 1) + ": ");
            entries.add(new StringEntry(scanner.nextLine()));
        }

        entries.sort(Comparator.comparingInt(
                (StringEntry entry) -> entry.length
        ).reversed());

        int limit = Math.min(3, entries.size());

        System.out.println("\nLongest strings:");
        for (int i = 0; i < limit; i++) {
            StringEntry entry = entries.get(i);
            System.out.println("\"" + entry.text + "\" - Length: " + entry.length);
        }

        scanner.close();
    }
}
```
